/* @bw-begin — machine-readable; do not hand-edit.
 * @bw device attiny88
 * @bw clock 8000000
 * @bw pin led PB0 output
 * @bw script bw_task0 0 stage
 * @bw script bw_task1 1 stage
 * @bw-end */
#include <avr/io.h>
#include <avr/interrupt.h>
#include <avr/sleep.h>
#include <stdint.h>

#define F_CPU 8000000UL

/* Timer 1 in CTC mode ticks every millisecond: F_CPU/64 counts,
 * OCR1A picked so one compare = 1 ms exactly at this clock.
 * (ATtiny88 Timer0 has no CTC — Timer1 is the tick source.) */
#define BW_OCR1A ((uint16_t)(F_CPU / 64UL / 1000UL - 1UL))

/* One script = one cooperative task. Timer interrupts every millisecond;
 * tasks yield at every wait and at every loop iteration (Scratch's own
 * scheduling contract), so no task can starve the others. */
static volatile uint32_t bw_ms;
static uint8_t bw_calm;

ISR(TIMER1_COMPA_vect)
{
    bw_ms++;
}

/* A 32-bit read is not atomic on an 8-bit AVR; hold interrupts off. */
static uint32_t bw_now(void)
{
    uint32_t t;
    cli();
    t = bw_ms;
    sei();
    return t;
}

/* print/ask: no UART on this chip, so a software one, 9600 8N1, on PD6 (TX)
 * and PD7 (RX), ATTinyCore's pins. Full duplex: both directions are clocked
 * by OCR1B, the tick timer's free compare channel (8 us a count at F_CPU/64).
 * Times are CPU cycles. One service, run only from that compare interrupt
 * and with interrupts re-enabled, advances both streams; a frame start --
 * bw_putc, or the RX pin-change -- only stamps the counter and pulls the
 * next compare to now, so a start edge waits a few cycles, not a service. */
#define BW_BIT_CYCLES ((int16_t)(F_CPU / 9600UL))
/* A sample is taken this many cycles after its compare match (the interrupt
 * entry and the service up to the pin read) and a start edge is stamped a
 * little late too, so the first sample is aimed that much early. Measured
 * 2026-10-06: without it the samples sat 0.22-0.44 bit past the centres. */
#define BW_RX_LATE    240
#define BW_UART_TOP   ((uint16_t)(F_CPU / 64UL / 1000UL))   /* counts per timer period */
static volatile uint8_t bw_tx_busy, bw_tx_go, bw_tx_n, bw_tx_byte;
static volatile uint16_t bw_tx_stamp;
static int16_t bw_tx_due;
static volatile uint8_t bw_rx_on, bw_rx_go, bw_rx_n, bw_rx_byte;
static volatile uint16_t bw_rx_stamp;
static int16_t bw_rx_due;
static volatile uint8_t bw_rxq[32];
static volatile uint8_t bw_rx_head, bw_rx_tail;
static uint16_t bw_uart_ref;   /* the counter value the dues are measured from */
static volatile uint8_t bw_uart_busy; /* the service is running (preemptible) */
/* Counts from `from` to `to`, across the wrap (both within one period). */
static uint16_t bw_uart_since(uint16_t from, uint16_t to)
{
    return (to >= from) ? to - from : to + BW_UART_TOP - from;
}
/* Cycles since a frame-start stamp; negative when the stamp is newer than
 * `now` (the RX edge interrupted the service after it read the counter --
 * taken as an age, that read as a whole period and every bit fell due at once). */
static int16_t bw_uart_age(uint16_t stamp, uint16_t now)
{
    int16_t a = (int16_t)bw_uart_since(stamp, now);
    if (a > (int16_t)(BW_UART_TOP / 2)) a -= (int16_t)BW_UART_TOP;
    return (int16_t)(a * 64);
}
/* Advance both streams to now, act on what is due, arm the next event; go
 * round again if a start was posted meanwhile or the counter passed the
 * target. Runs only inside the compare interrupt, with interrupts on. */
static void bw_uart_service(void)
{
  for (;;) {
    uint16_t now = TCNT1L, k, t;
    int16_t el = (int16_t)(bw_uart_since(bw_uart_ref, now) << 6), next = 0x7FFF;
    bw_uart_ref = now;
    if (bw_tx_go) {                              /* a byte posted by bw_putc */
        bw_tx_go = 0;
        bw_tx_n = 0;
        bw_tx_due = (int16_t)(BW_BIT_CYCLES - bw_uart_age(bw_tx_stamp, now));
    } else if (bw_tx_busy) {
        bw_tx_due -= el;
    }
    while (bw_tx_busy && bw_tx_due <= 32) {
        if (bw_tx_n < 8) {
            if ((bw_tx_byte >> bw_tx_n) & 1) PORTD |= (1 << 6); else PORTD &= (uint8_t)~(1 << 6);
        } else if (bw_tx_n == 8) {
            PORTD |= (1 << 6);                      /* stop bit */
        } else {
            bw_tx_busy = 0;                           /* the stop bit has run its length */
        }
        bw_tx_n++;
        bw_tx_due += BW_BIT_CYCLES;
    }
    if (bw_tx_busy && bw_tx_due < next) next = bw_tx_due;
    if (bw_rx_go) {                              /* a start edge, stamped */
        bw_rx_go = 0;
        bw_rx_on = 1;
        bw_rx_n = 0;
        bw_rx_byte = 0;
        bw_rx_due = (int16_t)(BW_BIT_CYCLES + BW_BIT_CYCLES / 2 - BW_RX_LATE - bw_uart_age(bw_rx_stamp, now));
    } else if (bw_rx_on) {
        bw_rx_due -= el;
    }
    while (bw_rx_on && bw_rx_due <= 32) {
        uint8_t bit = (PIND >> 7) & 1;
        if (bw_rx_n < 8) {
            if (bit) bw_rx_byte |= (uint8_t)(1 << bw_rx_n);
            bw_rx_n++;
            bw_rx_due += BW_BIT_CYCLES;
        } else {                                  /* the stop bit */
            if (bit && ((bw_rx_head + 1) & 31) != bw_rx_tail) {
                bw_rxq[bw_rx_head] = bw_rx_byte;
                bw_rx_head = (uint8_t)((bw_rx_head + 1) & 31);
            }
            bw_rx_on = 0;
        }
    }
    if (bw_rx_on && bw_rx_due < next) next = bw_rx_due;
    cli();                                       /* arming races the start stamps */
    if (bw_tx_go || bw_rx_go) { sei(); continue; }
    if (next == 0x7FFF) {
        TIMSK1 &= (uint8_t)~(1 << OCIE1B);      /* idle: no events */
        bw_uart_busy = 0;
        sei();                                   /* before the ISR's long exit: a start edge waits for no epilogue */
        return;
    }
    k = (uint16_t)(next + 32) >> 6;               /* cycles -> counts, rounded */
    if (k < 1) k = 1;
    t = now + k;
    if (t >= BW_UART_TOP) t -= BW_UART_TOP;
    TIFR1 = (1 << OCF1B);                       /* stale flag first, then the target */
    OCR1B = (uint16_t)t;
    TIMSK1 |= (1 << OCIE1B);
    if (bw_uart_since(now, TCNT1L) < k) { bw_uart_busy = 0; sei(); return; }   /* armed ahead of the counter */
    TIMSK1 &= (uint8_t)~(1 << OCIE1B);
    sei();
  }
}
ISR(TIMER1_COMPB_vect)
{
    TIMSK1 &= (uint8_t)~(1 << OCIE1B);          /* no nesting of this one */
    bw_uart_busy = 1;                            /* a start meanwhile only posts its flag */
    sei();                                       /* a start edge may interrupt the service */
    bw_uart_service();
}
static void bw_putc(char c)
{
    uint8_t sreg;
    while (bw_tx_busy) ;                         /* the previous byte is still going out */
    sreg = SREG;
    cli();
    bw_tx_stamp = TCNT1L;
    PORTD &= (uint8_t)~(1 << 6);            /* start bit, now */
    bw_tx_byte = (uint8_t)c;
    bw_tx_busy = 1;
    bw_tx_go = 1;
    TIFR1 = (1 << OCF1B);
    { uint16_t s = TCNT1L + 2u; if (s >= BW_UART_TOP) s -= BW_UART_TOP; OCR1B = (uint16_t)s; }
    TIMSK1 |= (1 << OCIE1B);
    SREG = sreg;
}

/* ask: a falling edge on RX starts a frame. Stamp it and hand it to the
 * service, which samples each bit at its centre. */
ISR(PCINT2_vect)
{
    uint16_t edge = TCNT1L;
    if (bw_rx_on || bw_rx_go || (PIND & (1 << 7))) return;   /* inside a frame, or a rising edge */
    bw_rx_stamp = edge;
    bw_rx_go = 1;
    if (bw_uart_busy) return;                    /* the running service will see it */
    TIFR1 = (1 << OCF1B);
    { uint16_t s = TCNT1L + 2u; if (s >= BW_UART_TOP) s -= BW_UART_TOP; OCR1B = (uint16_t)s; }
    TIMSK1 |= (1 << OCIE1B);
}
static char bw_rx_take(void)
{
    char c = (char)bw_rxq[bw_rx_tail];
    bw_rx_tail = (uint8_t)((bw_rx_tail + 1) & 31);
    return c;
}

static void bw_print(const char *s)
{
    while (*s) bw_putc(*s++);
    bw_putc(13); bw_putc(10);
}

static void bw_print_num(long n)
{
    char buf[12]; unsigned char i = 0;
    unsigned long u;
    if (n < 0) { bw_putc(45); u = (unsigned long)(-n); } else { u = (unsigned long)n; }
    do { buf[i++] = (char)(48 + (u % 10)); u /= 10; } while (u);
    while (i) bw_putc(buf[--i]);
    bw_putc(13); bw_putc(10);
}

/* print pieces: text, numbers and the answer on one line. */
static void bw_put_s(const char *s) { while (*s) bw_putc(*s++); }
static void bw_put_end(void) { bw_putc(13); bw_putc(10); }
static void bw_put_n(long n)
{
    char buf[12]; unsigned char i = 0;
    unsigned long u;
    if (n < 0) { bw_putc(45); u = (unsigned long)(-n); } else { u = (unsigned long)n; }
    do { buf[i++] = (char)(48 + (u % 10)); u /= 10; } while (u);
    while (i) bw_putc(buf[--i]);
}
static char bw_ans[32];
static uint8_t bw_ans_len;
static void bw_put_answer(void) { uint8_t i; for (i = 0; i < bw_ans_len; i++) bw_putc(bw_ans[i]); }

/* ask ... and wait: the question goes out like a print; the answer is
 * the next line that comes in on the serial line. */
#define BW_RX_READY()  (bw_rx_head != bw_rx_tail)
#define BW_RX_BYTE()   bw_rx_take()
static char bw_line[32];
static uint8_t bw_line_len;
static void bw_ask(const char *q) { bw_put_s(q); bw_put_end(); bw_line_len = 0; }
/* Take what has arrived; 1 when a whole line is in (it is then the answer). */
static uint8_t bw_got_line(void)
{
    uint8_t i;
    while (BW_RX_READY()) {
        char c = BW_RX_BYTE();
        if (c == 13 || c == 10) {
            if (!bw_line_len) continue;          /* the LF after a CR */
            for (i = 0; i < bw_line_len; i++) bw_ans[i] = bw_line[i];
            bw_ans_len = bw_line_len;
            bw_line_len = 0;
            return 1;
        }
        if (c == 8 || c == 127) { if (bw_line_len) bw_line_len--; continue; }
        if (bw_line_len < 31) bw_line[bw_line_len++] = c;
    }
    return 0;
}
/* The answer as a number: Scratch casts "12" to 12 and "twelve" to 0. */
static long bw_answer(void)
{
    uint8_t i = 0, neg = 0, any = 0;
    long n = 0;
    while (i < bw_ans_len && bw_ans[i] == 32) i++;
    if (i < bw_ans_len && (bw_ans[i] == 45 || bw_ans[i] == 43)) { neg = bw_ans[i] == 45; i++; }
    for (; i < bw_ans_len && bw_ans[i] >= 48 && bw_ans[i] <= 57; i++) { n = n * 10 + (bw_ans[i] - 48); any = 1; }
    while (i < bw_ans_len && bw_ans[i] == 32) i++;
    if (!any || i != bw_ans_len) return 0;
    return neg ? -n : n;
}
/* answer = "text": the same letters, upper or lower case. */
static uint8_t bw_answer_is(const char *s)
{
    uint8_t i;
    for (i = 0; i < bw_ans_len; i++, s++) {
        char a = bw_ans[i], b = *s;
        if (!b) return 0;
        if (a >= 97 && a <= 122) a -= 32;
        if (b >= 97 && b <= 122) b -= 32;
        if (a != b) return 0;
    }
    return *s == 0;
}

/* 10-bit ADC, polled, AVcc reference. Channel = the A-pin number;
 * A6/A7 exist on the Nano as ADC-only pads and work here too. */
static long adc_read(unsigned char channel)
{
    ADMUX = (uint8_t)((1 << REFS0) | (channel & 0x0F));
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC)) ;
    return ADC;
}

/* chip temperature: ADC8 (MUX 1000) against the internal 1.1 V (REFS0 = 0 on this part). Typical
 * curve: 230 LSB at -40 C, 300 LSB at 25 C, 370 LSB at 85 C. Two
 * conversions: the first after a reference change only settles it. */
static long bw_chip_temp(void)
{
    long lsb, t100;
    uint8_t i;
    ADMUX = 0x08;
    for (i = 0; i < 2; i++) {
        ADCSRA |= (1 << ADSC);
        while (ADCSRA & (1 << ADSC)) ;
    }
    lsb = (long)ADC;
    if (lsb <= 300L) t100 = 2500L - (300L - lsb) * 6500L / 70L;
    else t100 = 2500L + (lsb - 300L) * 6000L / 70L;
    return (t100 + 50L + 100000L) / 100L - 1000L;   /* hundredths -> nearest degree */
}

/* REPEAT counters live across yields. */
static long bw_i1;

/* forward declarations — print helpers defined after the timer section */
static void bw_putc(char c);
static void bw_print(const char *s);
static void bw_print_num(long n);
static void bw_put_s(const char *s);
static void bw_put_n(long n);
static void bw_put_answer(void);
static void bw_put_end(void);
static void bw_ask(const char *q);
static uint8_t bw_got_line(void);
static long bw_answer(void);
static uint8_t bw_answer_is(const char *s);

static volatile unsigned int bw_task0_state;
/* when green flag clicked (script 1) */
static void bw_task0(void)
{
    switch (bw_task0_state) {
    case 0:
    PORTB |= (1 << 0);
    bw_put_s("Chip ");
    bw_put_n(bw_chip_temp());
    bw_put_s(" C");
    bw_put_end();
    bw_ask("Name?");
    bw_task0_state = 1;
    case 1:
    if (!(bw_got_line())) return;
    bw_put_s("Hi ");
    bw_put_answer();
    bw_put_end();
    }
    bw_task0_state = 0xFFFF;   /* ran to the end */
}

static volatile unsigned int bw_task1_state;
static volatile unsigned int bw_task1_until;
/* when green flag clicked (script 2) */
static void bw_task1(void)
{
    switch (bw_task1_state) {
    case 0:
    bw_task1_until = bw_now() + (50);
    bw_task1_state = 1;
    case 1:
    if ((int)(bw_now() - bw_task1_until) < 0) return;
    bw_i1 = (40);
    bw_task1_state = 2;
    case 2:
    if (bw_i1 > 0) {
        bw_print("....................");
        bw_i1--;
        bw_task1_state = 2;
        return;
    }
    }
    bw_task1_state = 0xFFFF;   /* ran to the end */
}

/* Register setup: ports, ADC, Timer 0. Kept out of main() so the program
 * body stands alone — a C -> blocks reader can then tell them apart. */
static void bw_setup(void)
{
    PORTB &= (uint8_t)~(1 << 0);      /* led: start OFF */
    DDRB |= (1 << 0);     /* led = PB0 output */
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);  /* on, /128 */
    TCCR1B = (1 << WGM12) | (1 << CS11) | (1 << CS10);  /* Timer 1 CTC, F_CPU/64 */
    OCR1A  = BW_OCR1A;             /* one compare = 1 ms */
    TIMSK1 = (1 << OCIE1A);        /* millisecond tick */
    PORTD |= (1 << 6);               /* TX idles high -- set before it drives */
    DDRD  |= (1 << 6);               /* PD6 = software-UART TX */
    PORTD |= (1 << 7);               /* PD7 = software-UART RX, pull-up */
    TCCR1B = (1 << WGM12) | (1 << CS11) | (1 << CS10);   /* Timer 1: CTC, F_CPU/64 */
    OCR1A  = (uint16_t)(F_CPU / 64UL / 1000UL - 1UL);
    PCMSK2 |= (1 << PCINT23); PCICR |= (1 << PCIE2);   /* RX: pin-change interrupt */
}

int main(void)
{
    bw_setup();
    set_sleep_mode(SLEEP_MODE_IDLE);  /* timers keep running; the tick wakes us */
    sleep_enable();
    sei();                         /* tick on */

    for (;;) {
        uint32_t pass_ms = bw_now();
        bw_task0();
        bw_task1();
        /* Two full passes inside one millisecond: sleep to the next
         * tick instead of spinning the core against it — the same
         * contract the pico target keeps (its DONE row has the 110x
         * measurement), spelled in avr-libc. The emulator adapter
         * fast-forwards the SLEEP opcode; silicon idles. */
        if (bw_now() == pass_ms) { if (++bw_calm >= 2u) { bw_calm = 0u; sleep_cpu(); } }
        else bw_calm = 0u;
    }
}
